#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * move-modules.php — the ROUND 3 TRAIN 1 module-move codemod.
 *
 * Moves the flat `agent/src` (224 files) and `cli/src` (48 files) trees into
 * per-module subdirectories WITHOUT touching a single `namespace` statement.
 * That is legal here because the classmap autoloader
 * (`agent/duo-classmap.php` / `cli/duo-classmap.php`, generated by
 * `tools/classmap-generate.php`) maps FQCN => path: directory and namespace
 * are already decoupled, so `agent/src/Kernel/Canon.php` may keep declaring
 * `namespace Duo;`. Nothing about the drop-in's dependency-free contract
 * changes: every hand-written `require_once` survives the move, re-pointed at
 * the file's new location.
 *
 * What actually has to change is every *path* that names a moved file:
 *
 *   1. `__DIR__`-relative requires inside the moved files themselves. A
 *      same-module target stays `__DIR__ . '/X.php'`; a cross-module target
 *      becomes `__DIR__ . '/../Kernel/X.php'`. The guarded form
 *      (`if (!class_exists(X::class, false)) { require_once __DIR__ . …; }`)
 *      is preserved by construction: the rewriter is token-aware and only
 *      ever replaces the string literal in a `__DIR__ . '<literal>'` pair.
 *   2. `dirname(__DIR__, N)` path bases inside moved files. A moved file sits
 *      one directory deeper, so every such base needs N+1 (the delta is
 *      computed from the actual old/new depths, so a nested module segment
 *      works too). Every site is listed in --plan; sites whose context is not
 *      a `. '<string>'` concatenation are additionally listed under REVIEW,
 *      because those are the ones a human should eyeball (`__DIR__` has no
 *      non-path meaning, so they are still rewritten — silently leaving a
 *      now-wrong directory would be worse than a rewrite a reviewer confirms).
 *   3. Literal `agent/src/<Basename>.php` / `cli/src/<Basename>.php` strings
 *      anywhere in the repo — PHP requires, shell, Makefile, YAML, Markdown,
 *      phpstan-baseline `path:` lines. A negative lookbehind keeps
 *      `myagent/src/Canon.php` (a different, non-existent file that
 *      `tools/affected.php` deliberately refuses to resolve) out of the match.
 *      Directory-level mentions (`agent/src` not followed by `/<Basename>.php`)
 *      are left alone: `phpstan.neon.dist`'s `paths:` entries and
 *      `.gitignore`'s prose must not grow a module segment.
 *   4. The two loaders' root-relative requires: `agent/duo.php`'s 92
 *      `__DIR__ . '/src/X.php'` lines and `cli/duo`'s equivalents. Every other
 *      byte of those files — including the `define('DUO_AGENT_VERSION', …)` /
 *      `define('DUO_SPEC_VERSION', …)` lines that the registry and every
 *      certification bundle bind — is preserved.
 *   5. Four dynamic per-class requires that no path rewrite can reach, because
 *      the filename is a runtime variable:
 *      `cli/src/RefreshPlan.php::loadCompiler()` (39 names),
 *      `cli/src/AdapterCatalog.php::boot()`, `cli/src/AdapterDraft.php::boot()`
 *      and `cli/src/ManifestValidate.php::boot()`. Each is re-pointed through
 *      `agent/duo-classmap.php`, which is the only structure that still knows
 *      where a class lives after the move. Each rewrite asserts its exact
 *      expected snippet first and fails loudly if the source drifted.
 *   6. Data and scanner files: `tools/layers.json` keys, the sorted
 *      `tools/layers-exceptions.json` edge list (re-sorted after the rename,
 *      because `regress_agent_src_requires.php` requires SORT_STRING order),
 *      and the two non-recursive `glob($dir . '/*.php')` scanners that would
 *      silently see zero files after the move —
 *      `sandbox/tests/regress_agent_src_requires.php:390` and
 *      `tools/affected.php`'s `af_class_map()` / `af_source_graph()`.
 *
 * `manifests/**` is deliberately NOT touched. Those files are digest-bound
 * certification evidence; their `closure.inputs` path lists are rewritten by
 * re-certifying, never by a codemod. Every mention there is reported instead.
 *
 * Usage:
 *   php tools/codemod/move-modules.php --plan
 *   php tools/codemod/move-modules.php --apply
 *   php tools/codemod/move-modules.php --plan --root=/path/to/tree --map=/path/to/modules.json --tree=agent
 *
 * The script is cwd-independent (every path derives from --root, default
 * `dirname(__DIR__, 2)`) and every function is requireable: the main guard
 * only fires when this file is the entry point, so
 * `tests/Tooling/MoveModulesTest.php` can call the pieces directly.
 */

// --------------------------------------------------------------- constants

/**
 * Repo-relative trees whose text files are scanned for literal
 * `agent/src/X.php` / `cli/src/X.php` mentions. `manifests/` is absent by
 * design (see the file header); `vendor/` and `sandbox/tmp/` are scratch.
 */
const MM_SCAN_ROOTS = [
    '.github',
    'agent',
    'cli',
    'docs',
    'recovery',
    'sandbox',
    'scripts',
    'spec',
    'tests',
    'tools',
];

/** Repo-root files scanned alongside MM_SCAN_ROOTS. */
const MM_SCAN_FILES = [
    '.gitignore',
    '.php-cs-fixer.dist.php',
    'AGENTS.md',
    'CLAUDE.md',
    'DESIGN.md',
    'Makefile',
    'README.md',
    'composer.json',
    'phpstan-baseline.neon',
    'phpstan.neon.dist',
    'phpunit.xml.dist',
];

/**
 * Path prefixes never scanned or rewritten.
 *
 * `tools/codemod/` and its self-test are excluded for a reason particular to
 * this tool: they speak ABOUT the pre-move layout by construction. Its
 * expectation table is keyed on pre-move paths (`cli/src/RefreshPlan.php`),
 * its synthetic-repo test asserts `git mv agent/src/Canon.php
 * agent/src/Kernel/Canon.php`, and rewriting either would make the codemod
 * describe a move it can no longer perform and the test assert a tautology.
 * The stale-looking paths in this file's prose are the historical ones on
 * purpose: it documents a migration away from them.
 */
const MM_SCAN_EXCLUDE = [
    '.git/',
    '.phpunit.cache/',
    'manifests/',
    'sandbox/tmp/',
    'tests/Tooling/MoveModulesTest.php',
    'tools/codemod/',
    'vendor/',
];

/** Files larger than this are assumed to be fixtures, not source. */
const MM_MAX_SCAN_BYTES = 4194304;

/**
 * Certification-closure members, for the `CLOSURE (apply in train)` label in
 * --plan. Deliberately a *labelling* approximation of
 * `\Duo\ScopedCertificationBundle::subjectInputPaths()` — ask
 * `php tools/cert-impact.php` for the authoritative answer. It exists so a
 * reader of the plan can see at a glance which rewrites are the ones that buy
 * the certification round this train is paying for.
 */
const MM_CLOSURE_PREFIXES = ['agent/', 'cli/', 'sandbox/bin/', 'manifests/'];

const MM_CLOSURE_FILES = [
    'Makefile',
    'docs/compatibility-baseline.json',
    'sandbox/conformance/asserts.sh',
    'sandbox/conformance/run.sh',
    'sandbox/db.yml',
    'sandbox/init-cli.Dockerfile',
    'sandbox/tests/certify_subject_bundle.sh',
    'sandbox/tests/certify_version_matrix.sh',
    'sandbox/tests/regress_multisite_refusal.sh',
    'scripts/capability-registry.php',
];

// ------------------------------------------------------------ path helpers

/** Textual normalisation of `.`/`..` segments; never touches the filesystem. */
function mm_norm(string $path): string
{
    $absolute = str_starts_with($path, '/');
    $out = [];
    foreach (explode('/', $path) as $segment) {
        if ($segment === '' || $segment === '.') {
            continue;
        }
        if ($segment === '..') {
            if ($out !== [] && end($out) !== '..') {
                array_pop($out);
                continue;
            }
            if ($absolute) {
                continue;
            }
        }
        $out[] = $segment;
    }
    return ($absolute ? '/' : '') . implode('/', $out);
}

/** Relative path from directory `$from` to path `$to`; both must be normalised. */
function mm_relpath(string $from, string $to): string
{
    $fromParts = $from === '' ? [] : explode('/', trim($from, '/'));
    $toParts = $to === '' ? [] : explode('/', trim($to, '/'));
    while ($fromParts !== [] && $toParts !== [] && $fromParts[0] === $toParts[0]) {
        array_shift($fromParts);
        array_shift($toParts);
    }
    return implode('/', array_merge(array_fill(0, count($fromParts), '..'), $toParts));
}

function mm_dirname_rel(string $relative): string
{
    $slash = strrpos($relative, '/');
    return $slash === false ? '' : substr($relative, 0, $slash);
}

/** Directory depth of a repo-relative path, i.e. how many directories contain it. */
function mm_depth(string $relative): int
{
    return substr_count($relative, '/');
}

function mm_is_excluded(string $relative): bool
{
    foreach (MM_SCAN_EXCLUDE as $prefix) {
        if (str_starts_with($relative, $prefix)) {
            return true;
        }
    }
    return false;
}

function mm_is_closure(string $relative): bool
{
    foreach (MM_CLOSURE_PREFIXES as $prefix) {
        if (str_starts_with($relative, $prefix)) {
            return true;
        }
    }
    if (in_array($relative, MM_CLOSURE_FILES, true)) {
        return true;
    }
    return (bool) (preg_match('#^sandbox/(lib/pair_[^/]+\.sh|pair[^/]*\.yml)$#D', $relative));
}

// ------------------------------------------------------------- map loading

/**
 * @return array{trees: array<string, array{root: string, modules: array<string, list<string>>, keep: list<string>}>}
 */
function mm_load_map(string $mapPath, array $wantedTrees): array
{
    $raw = @file_get_contents($mapPath);
    if (!is_string($raw)) {
        throw new RuntimeException("move-modules: cannot read module map $mapPath");
    }
    $decoded = json_decode($raw, true);
    if (!is_array($decoded)) {
        throw new RuntimeException("move-modules: $mapPath is not a JSON object");
    }

    $trees = [];
    foreach ($decoded as $treeName => $treeSpec) {
        $treeName = (string) $treeName;
        if ($wantedTrees !== ['all'] && !in_array($treeName, $wantedTrees, true)) {
            continue;
        }
        // The map is a documented file, not a bare tree list: it also carries
        // `$comment`, `ladder`, `rules` and `not_moved` at top level. A key is
        // a tree only when it carries BOTH a string `root` and a `modules`
        // object; anything else is prose and is skipped. An explicitly
        // requested --tree that fails this test is still an error, so a typo
        // in the map cannot silently move nothing.
        $isTree = is_array($treeSpec)
            && isset($treeSpec['root']) && is_string($treeSpec['root'])
            && isset($treeSpec['modules']) && is_array($treeSpec['modules']);
        if (!$isTree) {
            if ($wantedTrees !== ['all']) {
                throw new RuntimeException(
                    "move-modules: '$treeName' is not a tree in $mapPath — a tree carries a string 'root' and a 'modules' object"
                );
            }
            continue;
        }
        $modules = [];
        foreach ($treeSpec['modules'] as $moduleName => $moduleSpec) {
            $moduleName = (string) $moduleName;
            $files = is_array($moduleSpec) ? ($moduleSpec['files'] ?? null) : null;
            if (!is_array($files)) {
                throw new RuntimeException("move-modules: module '$treeName/$moduleName' has no 'files' list");
            }
            $modules[$moduleName] = array_values(array_map('strval', $files));
        }
        $keep = [];
        if (isset($treeSpec['keep']) && is_array($treeSpec['keep'])) {
            $keep = array_values(array_map('strval', $treeSpec['keep']));
        }
        $trees[$treeName] = [
            'root' => rtrim(str_replace('\\', '/', $treeSpec['root']), '/'),
            'modules' => $modules,
            'keep' => $keep,
        ];
    }

    if ($trees === []) {
        throw new RuntimeException('move-modules: the module map selects no trees');
    }
    return ['trees' => $trees];
}

// --------------------------------------------------------- move computation

/**
 * Resolve the map against the tree on disk.
 *
 * Refuses (by throwing) when a file is unassigned, assigned twice, or named by
 * the map but absent from both its old and its new location. Re-running after
 * a completed --apply is a no-op: a file already at its module path is
 * recorded under `already` and moved again by nobody.
 *
 * @return array{
 *   placement: array<string,string>,
 *   moves: array<string,string>,
 *   already: array<string,string>,
 *   index: array<string, array<string,string>>,
 *   roots: array<string,string>
 * }
 */
function mm_build_moves(string $root, array $map, bool $allowPartial = false): array
{
    $placement = [];
    $moves = [];
    $already = [];
    $index = [];
    $roots = [];
    $errors = [];

    foreach ($map['trees'] as $treeName => $tree) {
        $treeRoot = $tree['root'];
        $roots[$treeName] = $treeRoot;
        $index[$treeName] = [];
        $assignedBy = [];

        $keep = [];
        foreach ($tree['keep'] as $file) {
            $keep[$file] = true;
        }

        foreach ($tree['modules'] as $moduleName => $files) {
            $segment = ($moduleName === '.' || $moduleName === '') ? '' : trim($moduleName, '/');
            foreach ($files as $file) {
                $file = ltrim(str_replace('\\', '/', $file), '/');
                if (isset($assignedBy[$file])) {
                    $errors[] = "$treeRoot/$file is assigned to both '{$assignedBy[$file]}' and '$moduleName'";
                    continue;
                }
                $assignedBy[$file] = $moduleName;

                $effective = isset($keep[$file]) ? '' : $segment;
                $oldRel = $treeRoot . '/' . $file;
                $newRel = $effective === '' ? $oldRel : $treeRoot . '/' . $effective . '/' . $file;

                $oldExists = is_file($root . '/' . $oldRel);
                $newExists = is_file($root . '/' . $newRel);
                if (!$oldExists && !$newExists) {
                    $errors[] = "$oldRel is named by module '$treeName/$moduleName' but exists at neither its old nor its new path";
                    continue;
                }

                $placement[$oldRel] = $newRel;
                if ($newRel !== $oldRel) {
                    if ($oldExists) {
                        $moves[$oldRel] = $newRel;
                    } else {
                        $already[$oldRel] = $newRel;
                    }
                }
                $index[$treeName][basename($file, '.php')] = $effective;
            }
        }

        // Totality: every PHP file that is (or could be) in this tree must be
        // named. Scanning recursively means a partially-applied tree still
        // answers the question correctly.
        foreach ($allowPartial ? [] : mm_tree_php_files($root, $treeRoot) as $onDisk) {
            if (isset($placement[$onDisk])) {
                continue;
            }
            $isDestination = in_array($onDisk, $placement, true);
            if ($isDestination) {
                continue;
            }
            $errors[] = "$onDisk is not assigned to any module";
        }
    }

    if ($errors !== []) {
        sort($errors, SORT_STRING);
        throw new RuntimeException(
            "move-modules: the module map does not cover the tree:\n  - " . implode("\n  - ", $errors)
        );
    }

    ksort($placement, SORT_STRING);
    ksort($moves, SORT_STRING);
    ksort($already, SORT_STRING);
    foreach ($index as $treeName => $_) {
        ksort($index[$treeName], SORT_STRING);
    }

    return [
        'placement' => $placement,
        'moves' => $moves,
        'already' => $already,
        'index' => $index,
        'roots' => $roots,
    ];
}

/** @return list<string> repo-relative PHP files under `$treeRoot`, recursively */
function mm_tree_php_files(string $root, string $treeRoot): array
{
    $dir = $root . '/' . $treeRoot;
    if (!is_dir($dir)) {
        return [];
    }
    $out = [];
    $walk = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
    foreach ($walk as $entry) {
        if (!$entry instanceof SplFileInfo || !$entry->isFile() || $entry->getExtension() !== 'php') {
            continue;
        }
        $out[] = $treeRoot . '/' . str_replace('\\', '/', substr($entry->getPathname(), strlen($dir) + 1));
    }
    sort($out, SORT_STRING);
    return $out;
}

// ------------------------------------------------- token-aware __DIR__ pass

/** Decode a T_CONSTANT_ENCAPSED_STRING that carries no interpolation. */
function mm_decode_string(string $token): ?string
{
    $quote = $token[0] ?? '';
    if (($quote !== "'" && $quote !== '"') || substr($token, -1) !== $quote) {
        return null;
    }
    $body = substr($token, 1, -1);
    if ($quote === '"' && preg_match('/[$\\\\]/', $body) === 1) {
        // Interpolation or an escape whose decoding is not round-trippable
        // here; the caller reports it for review rather than guessing.
        if (preg_match('/[$]|\\\\[^\\\\\'"]/', $body) === 1) {
            return null;
        }
    }
    if ($quote === "'") {
        return str_replace(['\\\\', "\\'"], ['\\', "'"], $body);
    }
    return str_replace(['\\\\', '\\"'], ['\\', '"'], $body);
}

/** Re-encode a path literal in the original token's quote style. */
function mm_encode_string(string $value, string $quote): string
{
    if ($quote === '"') {
        return '"' . str_replace(['\\', '"', '$'], ['\\\\', '\\"', '\\$'], $value) . '"';
    }
    return "'" . str_replace(['\\', "'"], ['\\\\', "\\'"], $value) . "'";
}

/**
 * Re-base every `__DIR__`-relative path expression in a file that is moving
 * from `$oldRel` to `$newRel`.
 *
 * Returns the new source plus one record per rewritten site. `review` holds
 * the sites a human should confirm: `dirname(__DIR__, N)` used somewhere other
 * than a string concatenation, and any `__DIR__` whose neighbouring literal
 * could not be decoded (an interpolated path, which no static rewrite can
 * resolve).
 *
 * @param array<string,string> $placement oldRel => newRel for every mapped file
 * @return array{source: string, changes: list<array{line:int, from:string, to:string, kind:string}>, review: list<array{line:int, text:string, why:string}>}
 */
function mm_rewrite_dir_relative(string $source, string $oldRel, string $newRel, array $placement): array
{
    $tokens = token_get_all($source);
    $changes = [];
    $review = [];

    $oldDir = mm_dirname_rel($oldRel);
    $newDir = mm_dirname_rel($newRel);
    $delta = mm_depth($newRel) - mm_depth($oldRel);

    $count = count($tokens);
    $line = 1;

    /** next index whose token is significant (not whitespace/comment) */
    $next = static function (int $i) use ($tokens, $count): int {
        for ($j = $i + 1; $j < $count; $j++) {
            $t = $tokens[$j];
            if (is_array($t) && in_array($t[0], [T_WHITESPACE, T_COMMENT, T_DOC_COMMENT], true)) {
                continue;
            }
            return $j;
        }
        return $count;
    };
    $text = static fn(int $i): string => is_array($tokens[$i]) ? (string) $tokens[$i][1] : (string) $tokens[$i];
    $id = static fn(int $i): int|string => is_array($tokens[$i]) ? $tokens[$i][0] : $tokens[$i];

    for ($i = 0; $i < $count; $i++) {
        $token = $tokens[$i];
        $line = is_array($token) ? (int) $token[2] : $line;

        // --- dirname(__DIR__ [, N]) ---------------------------------------
        if (is_array($token) && $token[0] === T_STRING && strtolower((string) $token[1]) === 'dirname') {
            $open = $next($i);
            if ($open < $count && $id($open) === '(') {
                $arg = $next($open);
                if ($arg < $count && $id($arg) === T_DIR) {
                    $after = $next($arg);
                    $depthIndex = null;
                    $depthValue = 1;
                    $close = null;
                    if ($after < $count && $id($after) === ',') {
                        $num = $next($after);
                        if ($num < $count && $id($num) === T_LNUMBER && ctype_digit($text($num))) {
                            $depthIndex = $num;
                            $depthValue = (int) $text($num);
                            $maybeClose = $next($num);
                            if ($maybeClose < $count && $id($maybeClose) === ')') {
                                $close = $maybeClose;
                            }
                        }
                    } elseif ($after < $count && $id($after) === ')') {
                        $close = $after;
                    }

                    if ($close !== null && $delta !== 0) {
                        $newDepth = $depthValue + $delta;
                        if ($newDepth < 1) {
                            $review[] = [
                                'line' => $line,
                                'text' => mm_source_line($source, $line),
                                'why' => "dirname(__DIR__, $depthValue) would need depth $newDepth after the move",
                            ];
                        } else {
                            $before = 'dirname(__DIR__' . ($depthIndex === null ? '' : ', ' . $depthValue) . ')';
                            $afterText = 'dirname(__DIR__, ' . $newDepth . ')';
                            if ($depthIndex === null) {
                                // `dirname(__DIR__)` -> `dirname(__DIR__, N)`:
                                // splice the depth argument in before `)`.
                                $tokens[$close] = ', ' . $newDepth . ')';
                            } else {
                                $tokens[$depthIndex] = (string) $newDepth;
                            }
                            // Is this a path base, i.e. concatenated with a
                            // literal? Anything else is still rewritten (there
                            // is no non-path reading of __DIR__) but surfaces
                            // under REVIEW so a human confirms the call site.
                            $concat = $next($close);
                            $isPathBase = $concat < $count && $id($concat) === '.';
                            $changes[] = [
                                'line' => $line,
                                'from' => $before,
                                'to' => $afterText,
                                'kind' => $isPathBase ? 'dirname-base' : 'dirname-nonconcat',
                            ];
                            if (!$isPathBase) {
                                $review[] = [
                                    'line' => $line,
                                    'text' => mm_source_line($source, $line),
                                    'why' => "$before rewritten to $afterText but is not a `. '<string>'` path base — confirm the call site wants the pre-move directory",
                                ];
                            }
                        }
                    }
                    $i = $close ?? $i;
                    continue;
                }
            }
            continue;
        }

        // --- __DIR__ . '<literal>' ----------------------------------------
        if (is_array($token) && $token[0] === T_DIR) {
            $dot = $next($i);
            if ($dot >= $count || $id($dot) !== '.') {
                $review[] = [
                    'line' => $line,
                    'text' => mm_source_line($source, $line),
                    'why' => '__DIR__ is not concatenated with a literal; re-base by hand',
                ];
                continue;
            }
            $str = $next($dot);
            if ($str >= $count || $id($str) !== T_CONSTANT_ENCAPSED_STRING) {
                $review[] = [
                    'line' => $line,
                    'text' => mm_source_line($source, $line),
                    'why' => '__DIR__ is concatenated with a non-literal expression; re-base by hand',
                ];
                continue;
            }
            $raw = $text($str);
            $literal = mm_decode_string($raw);
            if ($literal === null) {
                $review[] = [
                    'line' => $line,
                    'text' => mm_source_line($source, $line),
                    'why' => 'the path literal after __DIR__ interpolates; re-base by hand',
                ];
                continue;
            }

            $targetOld = mm_norm($oldDir . '/' . ltrim($literal, '/'));
            $targetNew = $placement[$targetOld] ?? $targetOld;
            $rebased = mm_relpath($newDir, $targetNew);
            $newLiteral = ($literal !== '' && $literal[0] === '/') ? '/' . $rebased : $rebased;
            if ($newLiteral !== $literal) {
                $encoded = mm_encode_string($newLiteral, $raw[0]);
                $tokens[$str] = $encoded;
                $changes[] = [
                    'line' => $line,
                    'from' => '__DIR__ . ' . $raw,
                    'to' => '__DIR__ . ' . $encoded,
                    'kind' => 'dir-relative',
                ];
            }
            $i = $str;
            continue;
        }
    }

    $out = '';
    foreach ($tokens as $token) {
        $out .= is_array($token) ? (string) $token[1] : (string) $token;
    }

    return ['source' => $out, 'changes' => $changes, 'review' => $review];
}

function mm_source_line(string $source, int $line): string
{
    $lines = explode("\n", $source);
    return trim($lines[$line - 1] ?? '');
}

// ------------------------------------------------ literal path-string pass

/**
 * The one regex the whole codemod hangs on.
 *
 * The lookbehind excludes name characters so `myagent/src/Canon.php` — which
 * `tools/affected.php` documents as a deliberately-unresolvable different file
 * — never grows a module segment, while `$root . '/agent/src/Canon.php'` and
 * `sandbox/tests/../../agent/src/Ledger.php` (both preceded by `/`) do.
 */
const MM_LITERAL_PATTERN = '#(?<![A-Za-z0-9_.\-])(agent|cli)((?:\.?\\\\?/)+)src((?:\.?\\\\?/)+)([A-Za-z0-9_]+)(\\\\?\.)php#';

/**
 * The separator groups are why the pattern is not simply `agent/src/X.php`.
 * Three real spellings in this tree mean the same file and all three must
 * follow the move together, or a test's input and its expectation drift apart:
 *
 *   agent/src/Canon.php        the ordinary one
 *   agent/./src/Canon.php      tools/affected.php's normalisation fixture
 *   agent\/src\/PathSafety\.php  the same path inside a regex literal
 *                              (tests/Tooling/AffectedTest.php:239)
 *
 * The matched separators are re-used verbatim when the module segment is
 * spliced in, so an escaped path stays escaped. `agent..src` has no slash and
 * so does not match; a directory-level `agent/src` has no `/<Name>.php` tail
 * and does not either.
 *
 * Anything still spelling a source path some other way is reported for review.
 */
const MM_NEARMISS_PATTERN = '#(?<![A-Za-z0-9_.\-])(agent|cli)[/.\\\\]+src[/.\\\\]+([A-Za-z0-9_]+)[\\\\]?\.php#';

/**
 * @param array<string, array<string,string>> $index tree => basename => module segment
 * @return array{text: string, changes: list<array{line:int, from:string, to:string, kind:string}>, unknown: list<array{line:int, path:string}>, nearmiss: list<array{line:int, text:string}>}
 */
function mm_rewrite_literals(string $text, array $index, array $roots): array
{
    unset($roots);
    $changes = [];
    $unknown = [];
    $nearmiss = [];

    $lines = explode("\n", $text);
    foreach ($lines as $n => $lineText) {
        $replaced = preg_replace_callback(
            MM_LITERAL_PATTERN,
            static function (array $m) use ($index, $n, &$unknown): string {
                $tree = $m[1];
                $base = $m[4];
                if (!isset($index[$tree])) {
                    return $m[0];
                }
                if (!array_key_exists($base, $index[$tree])) {
                    $unknown[] = ['line' => $n + 1, 'path' => $m[0]];
                    return $m[0];
                }
                $segment = $index[$tree][$base];
                if ($segment === '') {
                    return $m[0];
                }
                // $m[3] is the separator between `src` and the filename; the
                // module segment is spliced in using the same spelling, so an
                // escaped `\/` path stays escaped.
                return $tree . $m[2] . 'src' . $m[3] . $segment . $m[3] . $base . $m[5] . 'php';
            },
            $lineText
        );
        if (!is_string($replaced)) {
            throw new RuntimeException('move-modules: literal rewrite failed (preg error)');
        }
        if ($replaced !== $lineText) {
            $changes[] = [
                'line' => $n + 1,
                'from' => trim($lineText),
                'to' => trim($replaced),
                'kind' => 'literal-path',
            ];
            $lines[$n] = $replaced;
        }
        // Only a spelling the canonical pattern could NOT see is a near miss;
        // the near-miss pattern is a deliberate superset of it.
        if (preg_match(MM_NEARMISS_PATTERN, $lineText) === 1
            && preg_match(MM_LITERAL_PATTERN, $lineText) !== 1) {
            $nearmiss[] = ['line' => $n + 1, 'text' => trim($lineText)];
        }
    }

    return [
        'text' => implode("\n", $lines),
        'changes' => $changes,
        'unknown' => $unknown,
        'nearmiss' => $nearmiss,
    ];
}

// --------------------------------------------------------- loader rewrites

/**
 * `agent/duo.php`'s 92 `require_once __DIR__ . '/src/X.php'` lines and
 * `cli/duo`'s equivalents: the loader lives one level above the tree root, so
 * its requires are root-relative rather than `__DIR__`-sibling.
 *
 * @return array{text: string, changes: list<array{line:int, from:string, to:string, kind:string}>}
 */
function mm_rewrite_loader(string $text, string $treeRoot, array $treeIndex): array
{
    $leaf = basename($treeRoot);
    $pattern = '#__DIR__ \. ([\'"])/' . preg_quote($leaf, '#') . '/([A-Za-z0-9_]+)\.php\1#';
    $changes = [];

    $lines = explode("\n", $text);
    foreach ($lines as $n => $lineText) {
        $replaced = preg_replace_callback(
            $pattern,
            static function (array $m) use ($treeIndex, $leaf): string {
                $segment = $treeIndex[$m[2]] ?? '';
                if ($segment === '') {
                    return $m[0];
                }
                return '__DIR__ . ' . $m[1] . '/' . $leaf . '/' . $segment . '/' . $m[2] . '.php' . $m[1];
            },
            $lineText
        );
        if (is_string($replaced) && $replaced !== $lineText) {
            $changes[] = [
                'line' => $n + 1,
                'from' => trim($lineText),
                'to' => trim($replaced),
                'kind' => 'loader-require',
            ];
            $lines[$n] = $replaced;
        }
    }

    return ['text' => implode("\n", $lines), 'changes' => $changes];
}


/**
 * `<base> . '/src/<Name>.php'` with an arbitrary base — the shape an embedded
 * program uses when the tree root arrives as an argument rather than as
 * `__DIR__`:
 *
 *     // sandbox/tests/regress_scoped_certification_bundle.php:158, inside a
 *     // nowdoc program run as `php runner.php <agentDir> <manifestDir>`
 *     $agentDir = $argv[1];
 *     require $agentDir . '/src/Canon.php';
 *
 * No `agent/src/…` literal appears, and the base is bound in a different
 * process, so neither the literal rewriter nor the tree-root-variable rule can
 * see it. The filename is still resolvable — but only when it names a file in
 * exactly ONE tree. Four basenames (AdapterObservation, Init, Pending,
 * PlanView) exist under both agent/src and cli/src; for those the base decides
 * which is meant and the codemod cannot know it, so they are reported instead
 * of guessed.
 *
 * @return array{text:string, changes:list<array{line:int, from:string, to:string, kind:string}>, review:list<array{line:int, text:string, why:string}>}
 */
function mm_rewrite_root_parent_joins(string $text, array $index, array $roots): array
{
    $leaves = [];
    foreach ($roots as $treeName => $treeRoot) {
        if (isset($index[$treeName])) {
            $leaves[basename($treeRoot)][$treeName] = true;
        }
    }
    if ($leaves === []) {
        return ['text' => $text, 'changes' => [], 'review' => []];
    }

    $changes = [];
    $review = [];
    $lines = explode("\n", $text);

    foreach ($leaves as $leaf => $trees) {
        $quoted = preg_quote($leaf, '#');
        $pattern = "#(?P<open>\\. '/|\\. \"/|\\\$[A-Za-z0-9_]+/)" . $quoted
            . '/(?P<name>[A-Za-z0-9_]+)\\.php#';

        foreach ($lines as $n => $lineText) {
            if (!str_contains($lineText, '/' . $leaf . '/')) {
                continue;
            }
            $replaced = preg_replace_callback(
                $pattern,
                static function (array $m) use ($index, $trees, $leaf, $n, &$review, $lineText): string {
                    $owners = [];
                    foreach (array_keys($trees) as $treeName) {
                        if (isset($index[$treeName][$m['name']])) {
                            $owners[$treeName] = $index[$treeName][$m['name']];
                        }
                    }
                    if ($owners === []) {
                        return $m[0];
                    }
                    if (count($owners) > 1) {
                        $review[] = [
                            'line' => $n + 1,
                            'text' => trim($lineText),
                            'why' => "'/$leaf/{$m['name']}.php' names a file present in "
                                . implode(' and ', array_keys($owners))
                                . '; the base decides which and the codemod cannot — re-point by hand',
                        ];
                        return $m[0];
                    }
                    $segment = reset($owners);
                    if ($segment === '') {
                        return $m[0];
                    }
                    return $m['open'] . $leaf . '/' . $segment . '/' . $m['name'] . '.php';
                },
                $lineText
            );
            if (is_string($replaced) && $replaced !== $lineText) {
                $changes[] = [
                    'line' => $n + 1,
                    'from' => trim($lineText),
                    'to' => trim($replaced),
                    'kind' => 'root-parent-join',
                ];
                $lines[$n] = $replaced;
            }
        }
        $text = implode("\n", $lines);
    }

    return ['text' => $text, 'changes' => $changes, 'review' => $review];
}

// ------------------------------------------------ dynamic per-class requires

/**
 * Templated per-class requires: `require_once "$root/agent/src/$file.php";`
 * inside a `foreach ([...] as $file)`. The filename is a runtime value, so no
 * path rewrite reaches them; they are re-pointed through
 * `agent/duo-classmap.php`, the one structure that still knows where
 * `Duo\<Name>` lives after the move.
 *
 * One rule covers all of them because they are all the same shape: the four
 * cli/src boot() sites the train brief names
 * (`AdapterCatalog`, `AdapterDraft`, `ManifestValidate`, `RefreshPlan`) and the
 * five sandbox suites that boot the engine the same way
 * (`regress_scope_closure.php`, `regress_scope_contract.php`,
 * `regress_scoped_apply_recovery.php`, `regress_code_compatibility.sh`,
 * `regress_code_descriptor_unit.sh` — the last two inside a `php <<'PHP'`
 * heredoc, which is why this is a text rule and not a PHP-only one).
 *
 * The three concatenation spellings in the tree, all requiring the loop
 * variable to be the filename:
 *   "$repo/agent/src/$class.php"
 *   $repo . "/agent/src/$class.php"
 *   $root . '/agent/src/' . $file . '.php'
 */
const MM_TEMPLATED_FOREACH = '#(?P<indent>[ \t]*)foreach \((?P<list>\[[^\]]*\]) as \$(?P<var>[A-Za-z0-9_]+)\) \{\n'
    . "(?P<body>[ \t]*)require(?:_once)? (?P<expr>[^;\n]*);\n[ \t]*\}#";

/**
 * The sites the train brief names explicitly. After the generic pass every one
 * of them must have been rewritten; if the source drifted so the pattern no
 * longer matches, that is a hard failure rather than a silently-skipped file,
 * because the require it leaves behind would fatal at runtime.
 *
 * @return array<string,string> repo-relative path => exception-message label
 */
function mm_dynamic_sites(): array
{
    return [
        'cli/src/AdapterCatalog.php' => 'adapter',
        'cli/src/AdapterDraft.php' => 'adapter-draft',
        'cli/src/ManifestValidate.php' => 'manifest-validate',
        'cli/src/RefreshPlan.php' => 'refresh',
    ];
}

/** The classmap base expression a templated require must resolve through. */
function mm_templated_expr_base(string $expr, string $var): ?string
{
    $v = preg_quote($var, '#');
    $forms = [
        '#^"\$(?P<base>[A-Za-z0-9_]+)/agent/src/\$' . $v . '\.php"$#D',
        '#^\$(?P<base>[A-Za-z0-9_]+) \. "/agent/src/\$' . $v . '\.php"$#D',
        "#^\\\$(?P<base>[A-Za-z0-9_]+) \\. '/agent/src/' \\. \\\$" . $v . " \\. '\\.php'$#D",
    ];
    foreach ($forms as $form) {
        if (preg_match($form, $expr, $m) === 1) {
            return '$' . $m['base'];
        }
    }
    return null;
}

/**
 * @return array{text:string, changes:list<array{line:int, from:string, to:string, kind:string}>, names:list<string>}
 */
function mm_rewrite_templated_requires(string $text, string $relative): array
{
    $label = mm_dynamic_sites()[$relative] ?? basename($relative, '.' . pathinfo($relative, PATHINFO_EXTENSION));
    $changes = [];
    $names = [];

    $found = preg_match_all(MM_TEMPLATED_FOREACH, $text, $matches, PREG_SET_ORDER);
    if ($found === false) {
        throw new RuntimeException("move-modules: templated-require pattern failed on $relative (preg error)");
    }

    foreach ($matches as $m) {
        $base = mm_templated_expr_base(trim($m['expr']), $m['var']);
        if ($base === null) {
            continue;
        }
        $indent = $m['indent'];
        $body = $m['body'];
        $inner = $body . '    ';
        $var = '$' . $m['var'];

        // Indexed by the mapped path's BASENAME, not by class name: the loop
        // value is a FILE name, and three agent/src files declare a primary
        // type whose name differs from the filename — agent/src/CommandRefusal
        // .php declares Duo\CommandRefusalException, so a `Duo\' . $name`
        // lookup would miss it and turn a working require into a fatal.
        $replacement = $indent . '$duoAgentClassmap = require ' . $base . " . '/agent/duo-classmap.php';\n"
            . $indent . 'if (!is_array($duoAgentClassmap)) {' . "\n"
            . $indent . "    throw new \\RuntimeException('$label: agent/duo-classmap.php did not return a map');\n"
            . $indent . "}\n"
            . $indent . "\$duoAgentFiles = [];\n"
            . $indent . "foreach (\$duoAgentClassmap as \$duoAgentPath) {\n"
            . $indent . "    \$duoAgentFiles[basename((string) \$duoAgentPath, '.php')] = (string) \$duoAgentPath;\n"
            . $indent . "}\n"
            . $indent . 'foreach (' . $m['list'] . ' as ' . $var . ") {\n"
            . $body . '$duoAgentFile = $duoAgentFiles[' . $var . "] ?? null;\n"
            . $body . "if (!is_string(\$duoAgentFile)) {\n"
            . $inner . "throw new \\RuntimeException('$label: agent source ' . " . $var . " . '.php is absent from agent/duo-classmap.php');\n"
            . $body . "}\n"
            . $body . 'require_once ' . $base . " . '/agent/' . \$duoAgentFile;\n"
            . $indent . '}';

        $text = str_replace($m[0], $replacement, $text);
        $changes[] = ['line' => 0, 'from' => $m[0], 'to' => $replacement, 'kind' => 'templated-require'];
        if (preg_match_all("#'([A-Za-z0-9_]+)'#", $m['list'], $entries) > 0) {
            foreach ($entries[1] as $name) {
                $names[$name] = true;
            }
        }
    }

    return ['text' => $text, 'changes' => $changes, 'names' => array_keys($names)];
}


/**
 * Templated joins whose list is a set of bare class names:
 *
 *     foreach (['StatusCommand', 'PendingCommand', 'Init'] as $parser) {
 *         ... parity_literals($duoRoot . '/cli/src/' . $parser . '.php') ...
 *     }
 *
 * The path never appears as a literal, so the literal rewriter cannot see it,
 * and there is no require to hang a classmap lookup on. The list entries are
 * the resolvable half: prefixing each with its module segment makes the join
 * produce the right path AND keeps the suite's own `cli/src/$parser.php`
 * diagnostics accurate.
 *
 * All-or-nothing per list: if any entry is not a file the map places, the list
 * is left alone and reported, because a partially-prefixed list would build
 * paths that silently do not exist.
 *
 * @return array{text:string, changes:list<array{line:int, from:string, to:string, kind:string}>, review:list<array{line:int, text:string, why:string}>}
 */
function mm_rewrite_templated_lists(string $text, array $index, array $roots): array
{
    $changes = [];
    $review = [];

    foreach ($roots as $treeName => $treeRoot) {
        if (!isset($index[$treeName])) {
            continue;
        }
        $quoted = preg_quote($treeRoot, '#');
        $joins = '#(?:\'/' . $quoted . '/\' \. \$([A-Za-z0-9_]+) \. \'\.php\')'
            . '|(?:"[^"]*/' . $quoted . '/\$([A-Za-z0-9_]+)\.php")#';
        if (preg_match_all($joins, $text, $hits, PREG_SET_ORDER) === 0) {
            continue;
        }

        $vars = [];
        foreach ($hits as $hit) {
            $var = ($hit[1] ?? '') !== '' ? $hit[1] : ($hit[2] ?? '');
            if ($var !== '') {
                $vars[$var] = true;
            }
        }

        foreach (array_keys($vars) as $var) {
            $loop = '#foreach \((?P<list>\[[^\]]*\]) as \$' . preg_quote($var, '#') . '\)#';
            if (preg_match_all($loop, $text, $loops, PREG_SET_ORDER) === 0) {
                continue;
            }
            foreach ($loops as $found) {
                $list = $found['list'];
                if (preg_match_all("#'([A-Za-z0-9_]+)'#", $list, $entries) === 0) {
                    continue;
                }
                $unknown = [];
                foreach ($entries[1] as $name) {
                    if (!isset($index[$treeName][$name])) {
                        $unknown[] = $name;
                    }
                }
                if ($unknown !== []) {
                    $review[] = [
                        'line' => 1 + substr_count(substr($text, 0, (int) strpos($text, $found[0])), "\n"),
                        'text' => trim($found[0]),
                        'why' => 'templated ' . $treeRoot . ' list names ' . implode(', ', $unknown)
                            . ' which the map does not place; left alone rather than half-prefixed',
                    ];
                    continue;
                }
                $newList = preg_replace_callback(
                    "#'([A-Za-z0-9_]+)'#",
                    static function (array $m) use ($index, $treeName): string {
                        $segment = $index[$treeName][$m[1]];
                        return $segment === '' ? $m[0] : "'" . $segment . '/' . $m[1] . "'";
                    },
                    $list
                );
                if (!is_string($newList) || $newList === $list) {
                    continue;
                }
                $text = str_replace($found[0], str_replace($list, $newList, $found[0]), $text);
                $changes[] = [
                    'line' => 0,
                    'from' => $found[0],
                    'to' => str_replace($list, $newList, $found[0]),
                    'kind' => 'templated-list',
                ];
            }
        }
    }

    return ['text' => $text, 'changes' => $changes, 'review' => $review];
}

// ------------------------------------------------- tree-root variable paths

/**
 * A suite that binds the tree root to a variable
 * (`$realSrc = "$repoRoot/agent/src";`) then names files off it
 * (`"$realSrc/PublicationJournal.php"`) is invisible to the literal rewriter:
 * the text `agent/src/PublicationJournal.php` never appears. The variable is
 * resolvable though, so the module segment can be inserted after it.
 *
 * A `cp -R $realSrc $mutantSrc` makes the destination a copy of the same tree,
 * so it inherits the same treatment — `regress_capture_record_readback.php`
 * mutates a standalone copy of the engine and would otherwise look for a flat
 * one.
 *
 * @return array{text:string, changes:list<array{line:int, from:string, to:string, kind:string}>}
 */
function mm_rewrite_root_variables(string $text, array $index, array $roots): array
{
    $rootVars = [];
    foreach ($roots as $treeName => $treeRoot) {
        $pattern = '#\$([A-Za-z0-9_]+)\s*=[^;]*?(?<![A-Za-z0-9_.\-])'
            . preg_quote($treeRoot, '#') . '(?![/A-Za-z0-9_.])#';
        if (preg_match_all($pattern, $text, $m, PREG_SET_ORDER) > 0) {
            foreach ($m as $hit) {
                $rootVars[$hit[1]] = $treeName;
            }
        }
    }
    if ($rootVars === []) {
        return ['text' => $text, 'changes' => []];
    }

    // `cp -R <rootVar> <destVar>` — the destination is the same tree.
    if (preg_match_all('#cp -R[^\n]*?\$([A-Za-z0-9_]+)[^\n]*?\$([A-Za-z0-9_]+)#', $text, $m, PREG_SET_ORDER) > 0) {
        foreach ($m as $hit) {
            if (isset($rootVars[$hit[1]]) && !isset($rootVars[$hit[2]])) {
                $rootVars[$hit[2]] = $rootVars[$hit[1]];
            }
        }
    }

    $names = implode('|', array_map(static fn(string $v): string => preg_quote($v, '#'), array_keys($rootVars)));
    $changes = [];
    $lines = explode("\n", $text);
    foreach ($lines as $n => $lineText) {
        $replaced = preg_replace_callback(
            '#\$(' . $names . ')(?:"?)(/|\' \. \'/)([A-Za-z0-9_]+)\.php#',
            static function (array $hit) use ($rootVars, $index): string {
                $tree = $rootVars[$hit[1]] ?? null;
                if ($tree === null || !isset($index[$tree][$hit[3]]) || $index[$tree][$hit[3]] === '') {
                    return $hit[0];
                }
                return str_replace(
                    $hit[2] . $hit[3] . '.php',
                    $hit[2] . $index[$tree][$hit[3]] . '/' . $hit[3] . '.php',
                    $hit[0]
                );
            },
            $lineText
        );
        if (is_string($replaced) && $replaced !== $lineText) {
            $changes[] = ['line' => $n + 1, 'from' => trim($lineText), 'to' => trim($replaced), 'kind' => 'root-variable'];
            $lines[$n] = $replaced;
        }
    }

    return ['text' => implode("\n", $lines), 'changes' => $changes];
}

// -------------------------------------------- source-text assertion needles

/**
 * 45 offline suites assert a require *by its source text*:
 *
 *     $captureSource = file_get_contents(__DIR__ . '/../../agent/src/Capture.php');
 *     …
 *     str_contains($captureSource, "require_once __DIR__ . '/CapturePublicationWorkflow.php';")
 *
 * The move turns a cross-module require into `__DIR__ . '/../Engine/X.php'`, so
 * every one of those needles silently stops matching — and because they are
 * `str_contains()` assertions, they fail loudly rather than pass vacuously,
 * which is the only reason this is recoverable at all.
 *
 * The needle is rewritten by resolving which file the haystack variable was
 * loaded from: the assignment line names it as a literal
 * `agent/src/<Requirer>.php` path, so requirer and dependency are both known
 * and the new relative path is computable. A needle whose variable cannot be
 * resolved is left alone and reported — never guessed.
 *
 * @param array<string,string> $placement oldRel => newRel
 * @return array{text:string, changes:list<array{line:int, from:string, to:string, kind:string}>, review:list<array{line:int, text:string, why:string}>}
 */
function mm_rewrite_source_assertions(string $text, array $placement, array $roots): array
{
    $needle = '#"(require(?:_once)? __DIR__ \. )\'/([A-Za-z0-9_]+)\.php\'(;?)"#';
    if (preg_match($needle, $text) !== 1) {
        return ['text' => $text, 'changes' => [], 'review' => []];
    }

    $lines = explode("\n", $text);

    // Pass 1: variable => the repo-relative source file it was loaded from.
    // `null` marks a variable with two different origins, which is ambiguous
    // and therefore never rewritten.
    $origin = [];
    $remember = static function (string $var, string $path) use (&$origin): void {
        if (array_key_exists($var, $origin) && $origin[$var] !== $path) {
            $origin[$var] = null;
            return;
        }
        $origin[$var] = $path;
    };

    foreach ($lines as $lineText) {
        if (preg_match('#\$([A-Za-z0-9_]+)\s*=[^;]*?(?<![A-Za-z0-9_.\-])(agent|cli)/src/([A-Za-z0-9_]+)\.php#', $lineText, $m) === 1) {
            $remember($m[1], ($roots[$m[2]] ?? ($m[2] . '/src')) . '/' . $m[3] . '.php');
        }
    }

    // A handful of suites read their sources through a one-line loader closure
    // (`$source = fn(string $name) => file_get_contents("$root/agent/src/$name.php")`),
    // so the origin is the closure's ARGUMENT rather than a literal path. The
    // inference only fires when the file really does template a `src/` path
    // with a variable, and only for an argument that names a file the map
    // places — otherwise the needle is reported instead of guessed.
    $templated = [];
    foreach ($roots as $treeName => $treeRoot) {
        if (preg_match('#' . preg_quote($treeRoot, '#') . '/[^\'"]*\$#', $text) === 1) {
            $templated[$treeName] = $treeRoot;
        }
    }
    if ($templated !== []) {
        foreach ($lines as $lineText) {
            if (preg_match('#\$([A-Za-z0-9_]+)\s*=\s*\$[A-Za-z0-9_]+\(\s*\'([A-Za-z0-9_]+)\'\s*\)#', $lineText, $m) !== 1) {
                continue;
            }
            foreach ($templated as $treeRoot) {
                $candidate = $treeRoot . '/' . $m[2] . '.php';
                if (isset($placement[$candidate])) {
                    $remember($m[1], $candidate);
                    break;
                }
            }
        }
    }

    $changes = [];
    $review = [];

    foreach ($lines as $n => $lineText) {
        if (preg_match($needle, $lineText) !== 1) {
            continue;
        }

        // The haystack is whichever origin marker sits NEAREST before the
        // needle — either a variable whose load path pass 1 resolved, or a
        // literal `agent/src/X.php` inline in the same expression. The idiom
        // keeps them on one line, but a wrapped condition can push the marker
        // up to three lines back.
        $prefix = '';
        for ($back = 3; $back >= 1; $back--) {
            if ($n - $back >= 0) {
                $prefix .= $lines[$n - $back] . "\n";
            }
        }

        $replaced = preg_replace_callback(
            $needle,
            static function (array $m) use ($lineText, $prefix, $origin, $placement, $roots, $n, &$review): string {
                $before = $prefix . substr($lineText, 0, (int) strpos($lineText, $m[0]));
                $requirer = null;
                $markers = '#\$([A-Za-z0-9_]+)|(?<![A-Za-z0-9_.\-])(agent|cli)/src/([A-Za-z0-9_]+)\.php#';
                if (preg_match_all($markers, $before, $found, PREG_SET_ORDER) > 0) {
                    foreach (array_reverse($found) as $marker) {
                        if (($marker[2] ?? '') !== '') {
                            $requirer = ($roots[$marker[2]] ?? ($marker[2] . '/src')) . '/' . $marker[3] . '.php';
                            break;
                        }
                        if (!empty($origin[$marker[1]])) {
                            $requirer = $origin[$marker[1]];
                            break;
                        }
                    }
                }
                if ($requirer === null) {
                    $review[] = [
                        'line' => $n + 1,
                        'text' => trim($lineText),
                        'why' => "source-text needle {$m[0]}: cannot tell which file the haystack came from; re-point by hand",
                    ];
                    return $m[0];
                }

                $requirerNew = $placement[$requirer] ?? $requirer;
                $depOld = mm_dirname_rel($requirer) . '/' . $m[2] . '.php';
                $depNew = $placement[$depOld] ?? $depOld;
                $rebased = '/' . mm_relpath(mm_dirname_rel($requirerNew), $depNew);
                if ($rebased === '/' . $m[2] . '.php') {
                    return $m[0];
                }
                return '"' . $m[1] . "'" . $rebased . "'" . $m[3] . '"';
            },
            $lineText
        );

        if (is_string($replaced) && $replaced !== $lineText) {
            $changes[] = [
                'line' => $n + 1,
                'from' => trim($lineText),
                'to' => trim($replaced),
                'kind' => 'source-assertion',
            ];
            $lines[$n] = $replaced;
        }
    }

    return ['text' => implode("\n", $lines), 'changes' => $changes, 'review' => $review];
}

// ------------------------------------------------------ data-file rewrites

/**
 * `tools/layers.json` keys are `src/X.php` relative to `agent/`; the layer lint
 * in `sandbox/tests/regress_agent_src_requires.php` derives the same shape from
 * a recursive walk, so both halves must gain the module segment together.
 *
 * @return array{text: string, changes: int}
 */
function mm_rewrite_layers_json(string $text, array $agentIndex): array
{
    $decoded = json_decode($text, true);
    if (!is_array($decoded) || !isset($decoded['files']) || !is_array($decoded['files'])) {
        throw new RuntimeException('move-modules: tools/layers.json is not the expected {ladder,rule,files,notes} object');
    }
    $changes = 0;
    foreach (['files', 'notes'] as $section) {
        if (!isset($decoded[$section]) || !is_array($decoded[$section])) {
            continue;
        }
        $rewritten = [];
        foreach ($decoded[$section] as $key => $value) {
            $newKey = mm_map_src_key((string) $key, $agentIndex);
            if ($newKey !== (string) $key) {
                $changes++;
            }
            $rewritten[$newKey] = $value;
        }
        ksort($rewritten, SORT_STRING);
        $decoded[$section] = $rewritten;
    }
    return ['text' => mm_json_encode($decoded), 'changes' => $changes];
}

/**
 * `tools/layers-exceptions.json` is a sorted list of `A -> B` edges, and the
 * suite asserts SORT_STRING order (so a review diff is one line per changed
 * edge). Renaming both endpoints reorders the list, so it is re-sorted here.
 *
 * @return array{text: string, changes: int}
 */
function mm_rewrite_layers_exceptions(string $text, array $agentIndex): array
{
    $decoded = json_decode($text, true);
    if (!is_array($decoded) || $decoded !== array_values($decoded)) {
        throw new RuntimeException('move-modules: tools/layers-exceptions.json is not a JSON list');
    }
    $changes = 0;
    $out = [];
    foreach ($decoded as $entry) {
        $entry = (string) $entry;
        if (substr_count($entry, ' -> ') !== 1) {
            $out[] = $entry;
            continue;
        }
        [$from, $to] = explode(' -> ', $entry, 2);
        $rewritten = mm_map_src_key($from, $agentIndex) . ' -> ' . mm_map_src_key($to, $agentIndex);
        if ($rewritten !== $entry) {
            $changes++;
        }
        $out[] = $rewritten;
    }
    sort($out, SORT_STRING);
    return ['text' => mm_json_encode($out), 'changes' => $changes];
}

function mm_map_src_key(string $key, array $treeIndex): string
{
    if (preg_match('#^src/([A-Za-z0-9_]+)\.php$#D', $key, $m) !== 1) {
        return $key;
    }
    $segment = $treeIndex[$m[1]] ?? '';
    return $segment === '' ? $key : 'src/' . $segment . '/' . $m[1] . '.php';
}

/** Byte-identical to how tools/layers*.json are already formatted. */
function mm_json_encode(mixed $value): string
{
    $encoded = json_encode($value, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    if (!is_string($encoded)) {
        throw new RuntimeException('move-modules: could not encode JSON');
    }
    return $encoded . "\n";
}

