/**
 * `af_tree_php_files()` has no home in the diff-only rewrites above, so it is
 * appended next to the constant that names the trees it walks.
 */
const MM_AFFECTED_HELPER_ANCHOR = "const AF_SRC_DIRS = ['agent/src', 'cli/src', 'recovery'];";

const MM_AFFECTED_HELPER = <<<'PHP'

/**
 * Recursive since the module move (ROUND 3 TRAIN 1): agent/src and cli/src are
 * module directories now, so the previous `glob($dir . '/*.php')` would have
 * returned zero files and silently emptied both the class map and the source
 * graph. Returns repo-relative paths, which is what both callers key on.
 *
 * @return list<string>
 */
function af_tree_php_files(string $root, string $dir): array
{
    $base = $root . '/' . $dir;
    if (!is_dir($base)) {
        return [];
    }
    $out = [];
    $walk = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($base, FilesystemIterator::SKIP_DOTS));
    foreach ($walk as $entry) {
        if ($entry instanceof SplFileInfo && $entry->isFile() && $entry->getExtension() === 'php') {
            $out[] = $dir . '/' . str_replace('\\', '/', substr($entry->getPathname(), strlen($base) + 1));
        }
    }
    sort($out, SORT_STRING);
    return $out;
}
PHP;

// ---------------------------------------------------------------- scanning

/** @return list<string> repo-relative text files eligible for the literal pass */
function mm_scan_targets(string $root): array
{
    $out = [];
    foreach (MM_SCAN_ROOTS as $dir) {
        $base = $root . '/' . $dir;
        if (!is_dir($base)) {
            continue;
        }
        $walk = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($base, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::SELF_FIRST
        );
        foreach ($walk as $entry) {
            if (!$entry instanceof SplFileInfo || !$entry->isFile() || $entry->isLink()) {
                continue;
            }
            $relative = $dir . '/' . str_replace('\\', '/', substr($entry->getPathname(), strlen($base) + 1));
            if (mm_is_excluded($relative) || str_contains($relative, '/.git/')) {
                continue;
            }
            if ($entry->getSize() > MM_MAX_SCAN_BYTES) {
                continue;
            }
            $out[] = $relative;
        }
    }
    foreach (MM_SCAN_FILES as $file) {
        if (is_file($root . '/' . $file)) {
            $out[] = $file;
        }
    }
    sort($out, SORT_STRING);
    return $out;
}

function mm_is_text(string $bytes): bool
{
    return !str_contains(substr($bytes, 0, 8000), "\0");
}

function mm_is_php(string $relative, string $bytes): bool
{
    return str_ends_with($relative, '.php') || str_starts_with($bytes, "#!/usr/bin/env php\n<?php");
}

// -------------------------------------------------------------- the plan

/**
 * Compute every move and every rewrite. Pure: reads the tree, writes nothing.
 *
 * @return array{
 *   moves: array<string,string>, already: array<string,string>,
 *   placement: array<string,string>, index: array<string, array<string,string>>,
 *   roots: array<string,string>,
 *   files: array<string, array{closure: bool, moved: bool, text: ?string, changes: list<array<string,mixed>>}>,
 *   review: list<array{file:string, line:int, text:string, why:string}>,
 *   unknown: list<array{file:string, line:int, path:string}>,
 *   nearmiss: list<array{file:string, line:int, text:string}>,
 *   manifests: array<string,int>,
 *   dirname_sites: list<array{file:string, line:int, from:string, to:string, kind:string}>
 * }
 */
function mm_compute(string $root, array $map, bool $allowPartial = false): array
{
    $resolved = mm_build_moves($root, $map, $allowPartial);
    $placement = $resolved['placement'];
    $moves = $resolved['moves'];
    $already = $resolved['already'];
    $index = $resolved['index'];
    $roots = $resolved['roots'];

    // Effective placement includes the already-moved files, so a re-run
    // re-bases against the same targets it used the first time.
    $effective = $placement;

    $files = [];
    $review = [];
    $unknown = [];
    $nearmiss = [];
    $dirnameSites = [];

    $dynamic = mm_dynamic_sites();
    $rewrittenDynamic = [];
    $templatedNames = [];
    $scannerFixes = mm_scanner_fixes();

    foreach (mm_scan_targets($root) as $relative) {
        // A file that is moving is read from its OLD path but planned under
        // its NEW one, so the plan reads the way the applied tree will look.
        $sourcePath = $root . '/' . $relative;
        $bytes = @file_get_contents($sourcePath);
        if (!is_string($bytes) || !mm_is_text($bytes)) {
            continue;
        }

        $oldRel = $relative;
        $newRel = $effective[$relative] ?? $relative;
        $moved = isset($moves[$relative]) || isset($already[$relative]);

        $text = $bytes;
        $changes = [];

        // (1)(2) __DIR__ / dirname(__DIR__) re-basing, moved PHP files only.
        if ($moved && mm_is_php($relative, $bytes)) {
            $r = mm_rewrite_dir_relative($text, $oldRel, $newRel, $effective);
            $text = $r['source'];
            foreach ($r['changes'] as $c) {
                $changes[] = $c;
                if (str_starts_with($c['kind'], 'dirname')) {
                    $dirnameSites[] = ['file' => $newRel] + $c;
                }
            }
            foreach ($r['review'] as $v) {
                $review[] = ['file' => $newRel] + $v;
            }
        }

        // (4b) source-text require assertions, before the literal pass — the
        // haystack variable is resolved from the still-canonical
        // `agent/src/<Requirer>.php` path on its assignment line.
        $sa = mm_rewrite_source_assertions($text, $effective, $roots);
        $text = $sa['text'];
        foreach ($sa['changes'] as $c) {
            $changes[] = $c;
        }
        foreach ($sa['review'] as $v) {
            $review[] = ['file' => $relative] + $v;
        }

        // (5) templated per-class requires — before the literal pass, because
        // the snippet they match carries no rewritable literal.
        if (isset($index['agent'])) {
            $d = mm_rewrite_templated_requires($text, $oldRel);
            if ($d['changes'] !== []) {
                $text = $d['text'];
                foreach ($d['changes'] as $c) {
                    $changes[] = $c;
                }
                $rewrittenDynamic[$oldRel] = true;
                foreach ($d['names'] as $name) {
                    $templatedNames[$name] = true;
                }
            }
        }

        // (5a) templated joins over a list of bare class names, whose list
        // entries are the only resolvable half.
        $tl = mm_rewrite_templated_lists($text, $index, $roots);
        $text = $tl['text'];
        foreach ($tl['changes'] as $c) {
            $changes[] = $c;
        }
        foreach ($tl['review'] as $v) {
            $review[] = ['file' => $relative] + $v;
        }

        // (5b) tree-root variables: `$src = "$repo/agent/src"` then
        // `"$src/Name.php"`, which the literal rewriter cannot see.
        $rv = mm_rewrite_root_variables($text, $index, $roots);
        $text = $rv['text'];
        foreach ($rv['changes'] as $c) {
            $changes[] = $c;
        }

        // (4) the two loaders.
        foreach ($roots as $treeName => $treeRoot) {
            if ($relative !== mm_dirname_rel($treeRoot) . '/duo.php'
                && $relative !== mm_dirname_rel($treeRoot) . '/duo') {
                continue;
            }
            $l = mm_rewrite_loader($text, $treeRoot, $index[$treeName]);
            $text = $l['text'];
            foreach ($l['changes'] as $c) {
                $changes[] = $c;
            }
        }

        // (5c) `<base> . '/src/Name.php'` where the base is bound elsewhere.
        $rp = mm_rewrite_root_parent_joins($text, $index, $roots);
        $text = $rp['text'];
        foreach ($rp['changes'] as $c) {
            $changes[] = $c;
        }
        foreach ($rp['review'] as $v) {
            $review[] = ['file' => $relative] + $v;
        }

        // (6) scanner recursion fixes.
        if (isset($scannerFixes[$relative])) {
            foreach ($scannerFixes[$relative] as [$needle, $replacement, $occurrences]) {
                $seen = substr_count($text, $needle);
                if ($seen === 0) {
                    if (!str_contains($text, $replacement)) {
                        throw new RuntimeException(
                            "move-modules: expected scanner snippet not found in $relative — "
                            . 'the source drifted; update mm_scanner_fixes() rather than shipping a vacuous guard'
                        );
                    }
                    continue;
                }
                if ($seen !== $occurrences) {
                    throw new RuntimeException(
                        "move-modules: scanner snippet occurs $seen times in $relative; expected $occurrences"
                    );
                }
                $text = str_replace($needle, $replacement, $text);
                $changes[] = ['line' => 0, 'from' => $needle, 'to' => $replacement, 'kind' => 'scanner-recursion'];
            }
        }
        if ($relative === 'tools/affected.php'
            && str_contains($text, MM_AFFECTED_HELPER_ANCHOR)
            && !str_contains($text, 'function af_tree_php_files(')) {
            $text = str_replace(
                MM_AFFECTED_HELPER_ANCHOR,
                MM_AFFECTED_HELPER_ANCHOR . "\n" . MM_AFFECTED_HELPER,
                $text
            );
            $changes[] = [
                'line' => 0,
                'from' => MM_AFFECTED_HELPER_ANCHOR,
                'to' => '(+ af_tree_php_files() helper)',
                'kind' => 'scanner-recursion',
            ];
        }

        // (6) data files.
        if ($relative === 'tools/layers.json' && isset($index['agent'])) {
            $j = mm_rewrite_layers_json($text, $index['agent']);
            if ($j['changes'] > 0) {
                $text = $j['text'];
                $changes[] = ['line' => 0, 'from' => '(layers.json keys)', 'to' => $j['changes'] . ' keys re-pointed + re-sorted', 'kind' => 'layers-json'];
            }
        }
        if ($relative === 'tools/layers-exceptions.json' && isset($index['agent'])) {
            $j = mm_rewrite_layers_exceptions($text, $index['agent']);
            if ($j['changes'] > 0) {
                $text = $j['text'];
                $changes[] = ['line' => 0, 'from' => '(layers-exceptions.json edges)', 'to' => $j['changes'] . ' edges re-pointed + re-sorted', 'kind' => 'layers-json'];
            }
        }

        // (3) literal path strings, last, so it also covers the text the
        // rewrites above inserted.
        $lit = mm_rewrite_literals($text, $index, $roots);
        $text = $lit['text'];
        foreach ($lit['changes'] as $c) {
            $changes[] = $c;
        }
        foreach ($lit['unknown'] as $u) {
            $unknown[] = ['file' => $relative] + $u;
        }
        foreach ($lit['nearmiss'] as $u) {
            $nearmiss[] = ['file' => $relative] + $u;
        }

        if ($changes === [] && !$moved) {
            continue;
        }
        $files[$relative] = [
            'closure' => mm_is_closure($moved ? $newRel : $relative),
            'moved' => $moved,
            'new' => $newRel,
            'text' => $text === $bytes ? null : $text,
            'changes' => $changes,
        ];
    }

    // The four sites the train brief names must have been rewritten. A source
    // drift that stops the pattern matching would otherwise ship a require
    // that fatals at runtime, so it fails here instead. A tree that is already
    // applied carries the classmap form and is accepted.
    if (isset($index['agent'])) {
        foreach (array_keys($dynamic) as $site) {
            if (isset($rewrittenDynamic[$site]) || !is_file($root . '/' . ($placement[$site] ?? $site))) {
                continue;
            }
            $current = (string) file_get_contents($root . '/' . ($placement[$site] ?? $site));
            if (str_contains($current, '$duoAgentClassmap')) {
                continue;
            }
            throw new RuntimeException(
                "move-modules: expected templated per-class require not found in $site — the source "
                . 'drifted; update mm_dynamic_sites()/MM_TEMPLATED_FOREACH rather than letting the move '
                . 'ship a require that resolves to a path no longer on disk'
            );
        }
    }

    return [
        'templated_names' => array_keys($templatedNames),
        'moves' => $moves,
        'already' => $already,
        'placement' => $placement,
        'index' => $index,
        'roots' => $roots,
        'files' => $files,
        'review' => $review,
        'unknown' => $unknown,
        'nearmiss' => $nearmiss,
        'manifests' => mm_manifest_mentions($root),
        'dirname_sites' => $dirnameSites,
    ];
}

/** @return array<string,int> repo-relative manifests file => mention count */
function mm_manifest_mentions(string $root): array
{
    $dir = $root . '/manifests';
    if (!is_dir($dir)) {
        return [];
    }
    $out = [];
    $walk = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
    foreach ($walk as $entry) {
        if (!$entry instanceof SplFileInfo || !$entry->isFile() || $entry->getSize() > MM_MAX_SCAN_BYTES) {
            continue;
        }
        $bytes = @file_get_contents($entry->getPathname());
        if (!is_string($bytes) || !mm_is_text($bytes)) {
            continue;
        }
        $n = preg_match_all(MM_LITERAL_PATTERN, $bytes);
        if (is_int($n) && $n > 0) {
            $out['manifests/' . str_replace('\\', '/', substr($entry->getPathname(), strlen($dir) + 1))] = $n;
        }
    }
    ksort($out, SORT_STRING);
    return $out;
}

// --------------------------------------------------------------- reporting

function mm_print_plan(array $plan, array $map): void
{
    $out = STDOUT;

    fwrite($out, "=== MOVES ===\n");
    $perModule = [];
    foreach ($plan['placement'] as $oldRel => $newRel) {
        $perModule[mm_dirname_rel($newRel)][] = [$oldRel, $newRel];
    }
    ksort($perModule, SORT_STRING);
    foreach ($perModule as $dir => $rows) {
        $movingRows = array_values(array_filter($rows, static fn(array $r): bool => $r[0] !== $r[1]));
        $keptRows = count($rows) - count($movingRows);
        fwrite($out, sprintf("%s (%d files; %d already in place)\n", $dir, count($rows), $keptRows));
        foreach ($rows as [$oldRel, $newRel]) {
            if ($oldRel === $newRel) {
                fwrite($out, "    keep  $oldRel\n");
            } elseif (isset($plan['already'][$oldRel])) {
                fwrite($out, "    done  $oldRel -> $newRel\n");
            } else {
                fwrite($out, "    git mv $oldRel $newRel\n");
            }
        }
    }
    fwrite($out, sprintf(
        "\n%d move(s) pending, %d already applied, %d file(s) staying put.\n\n",
        count($plan['moves']),
        count($plan['already']),
        count($plan['placement']) - count($plan['moves']) - count($plan['already'])
    ));

    fwrite($out, "=== REWRITES ===\n");
    $closureFiles = [];
    foreach ($plan['files'] as $relative => $info) {
        if ($info['changes'] === []) {
            continue;
        }
        if ($info['closure']) {
            $closureFiles[$relative] = $info;
            continue;
        }
        mm_print_file_changes($out, $relative, $info);
    }

    fwrite($out, "\n=== CLOSURE (apply in train) ===\n");
    fwrite($out, "These rewrites land inside the certification closure. --apply performs\n");
    fwrite($out, "them, because the orchestrator runs --apply inside the certification\n");
    fwrite($out, "train that is already paying for the round. Ask `php tools/cert-impact.php`\n");
    fwrite($out, "for the authoritative membership.\n\n");
    foreach ($closureFiles as $relative => $info) {
        mm_print_file_changes($out, $relative, $info);
    }

    fwrite($out, "\n=== dirname(__DIR__) SITES ===\n");
    if ($plan['dirname_sites'] === []) {
        fwrite($out, "none\n");
    }
    foreach ($plan['dirname_sites'] as $site) {
        fwrite($out, sprintf(
            "%s:%d  %s -> %s  [%s]\n",
            $site['file'],
            $site['line'],
            $site['from'],
            $site['to'],
            $site['kind'] === 'dirname-base' ? 'path base' : 'NON-CONCAT: review'
        ));
    }
    fwrite($out, sprintf("%d site(s).\n", count($plan['dirname_sites'])));

    fwrite($out, "\n=== REVIEW (rewrite could not be proven safe) ===\n");
    if ($plan['review'] === [] && $plan['unknown'] === [] && $plan['nearmiss'] === []) {
        fwrite($out, "none\n");
    }
    foreach ($plan['review'] as $item) {
        fwrite($out, sprintf("%s:%d  %s\n      %s\n", $item['file'], $item['line'], $item['why'], $item['text']));
    }
    foreach ($plan['unknown'] as $item) {
        fwrite($out, sprintf("%s:%d  names %s, which the map does not assign (left untouched)\n", $item['file'], $item['line'], $item['path']));
    }
    foreach ($plan['nearmiss'] as $item) {
        fwrite($out, sprintf("%s:%d  non-canonical spelling the path rewriter cannot see (left untouched)\n      %s\n", $item['file'], $item['line'], $item['text']));
    }

    fwrite($out, "\n=== manifests/ (left untouched, digest-bound) ===\n");
    if ($plan['manifests'] === []) {
        fwrite($out, "none\n");
    }
    $total = 0;
    foreach ($plan['manifests'] as $relative => $n) {
        $total += $n;
        fwrite($out, sprintf("%-90s %d mention(s)\n", $relative, $n));
    }
    fwrite($out, sprintf(
        "%d file(s), %d mention(s) left untouched: certification evidence is re-earned by\n"
        . "re-certifying, never by rewriting a recorded closure path.\n",
        count($plan['manifests']),
        $total
    ));

    fwrite($out, "\n=== SUMMARY ===\n");
    mm_print_summary($out, $plan, $map);
}

function mm_print_file_changes($out, string $relative, array $info): void
{
    $header = $relative;
    if ($info['moved'] && $info['new'] !== $relative) {
        $header .= ' -> ' . $info['new'];
    }
    $tags = [];
    if ($info['moved']) {
        $tags[] = 'moved';
    }
    if ($info['closure']) {
        $tags[] = 'closure';
    }
    fwrite($out, sprintf("--- %s%s\n", $header, $tags === [] ? '' : '  [' . implode(', ', $tags) . ']'));
    foreach ($info['changes'] as $change) {
        if ($change['line'] > 0) {
            fwrite($out, sprintf("    L%-5d %s\n          -> %s\n", $change['line'], $change['from'], $change['to']));
            continue;
        }
        fwrite($out, sprintf("    [%s]\n", $change['kind']));
        foreach (explode("\n", rtrim($change['from'])) as $lineText) {
            fwrite($out, "      - $lineText\n");
        }
        foreach (explode("\n", rtrim($change['to'])) as $lineText) {
            fwrite($out, "      + $lineText\n");
        }
    }
}

function mm_print_summary($out, array $plan, array $map): void
{
    $perModule = [];
    foreach ($plan['moves'] as $newRel) {
        $perModule[mm_dirname_rel($newRel)] = ($perModule[mm_dirname_rel($newRel)] ?? 0) + 1;
    }
    ksort($perModule, SORT_STRING);
    foreach ($perModule as $dir => $n) {
        fwrite($out, sprintf("  moved  %-40s %d file(s)\n", $dir, $n));
    }

    $byKind = [];
    $rewrittenFiles = 0;
    foreach ($plan['files'] as $info) {
        if ($info['changes'] === []) {
            continue;
        }
        $rewrittenFiles++;
        foreach ($info['changes'] as $change) {
            $byKind[$change['kind']] = ($byKind[$change['kind']] ?? 0) + 1;
        }
    }
    ksort($byKind, SORT_STRING);
    fwrite($out, sprintf("  %d file(s) rewritten\n", $rewrittenFiles));
    foreach ($byKind as $kind => $n) {
        fwrite($out, sprintf("    %-22s %d\n", $kind, $n));
    }
    fwrite($out, sprintf("  %d dirname(__DIR__) site(s)\n", count($plan['dirname_sites'])));
    fwrite($out, sprintf("  %d review item(s)\n", count($plan['review']) + count($plan['unknown']) + count($plan['nearmiss'])));
    fwrite($out, sprintf("  %d manifests/ file(s) left untouched\n", count($plan['manifests'])));
    unset($map);
}

// ------------------------------------------------------------------- apply

/**
 * @return array{moved: int, rewritten: int, lint_failures: list<string>, notes: list<string>}
 */
function mm_apply(string $root, array $plan): array
{
    $notes = [];
    $touchedPhp = [];

    // 1. Write every rewritten file, at its OLD path — the move comes next, so
    //    `git mv` still sees the file where the index expects it.
    $rewritten = 0;
    foreach ($plan['files'] as $relative => $info) {
        if ($info['text'] === null) {
            continue;
        }
        $path = $root . '/' . $relative;
        if (file_put_contents($path, $info['text']) === false) {
            throw new RuntimeException("move-modules: cannot write $relative");
        }
        $rewritten++;
    }

    // 2. Move.
    $moved = 0;
    $isGit = is_dir($root . '/.git');
    foreach ($plan['moves'] as $oldRel => $newRel) {
        $targetDir = $root . '/' . mm_dirname_rel($newRel);
        if (!is_dir($targetDir) && !mkdir($targetDir, 0755, true) && !is_dir($targetDir)) {
            throw new RuntimeException("move-modules: cannot create $targetDir");
        }
        $done = false;
        if ($isGit) {
            $cmd = 'git -C ' . escapeshellarg($root) . ' mv -- '
                . escapeshellarg($oldRel) . ' ' . escapeshellarg($newRel) . ' 2>&1';
            exec($cmd, $output, $status);
            $done = $status === 0;
            if (!$done) {
                $notes[] = "git mv refused $oldRel (" . trim(implode(' ', $output)) . '); fell back to rename()';
            }
            $output = [];
        }
        if (!$done && !rename($root . '/' . $oldRel, $root . '/' . $newRel)) {
            throw new RuntimeException("move-modules: cannot move $oldRel to $newRel");
        }
        $moved++;
    }

    // 3. Collect every moved/rewritten PHP file for the lint sweep, now at
    //    their post-move paths.
    foreach ($plan['files'] as $relative => $info) {
        $final = $info['moved'] ? $info['new'] : $relative;
        if ($info['text'] === null && !$info['moved']) {
            continue;
        }
        $path = $root . '/' . $final;
        if (!is_file($path)) {
            continue;
        }
        $head = (string) file_get_contents($path, false, null, 0, 64);
        if (mm_is_php($final, $head)) {
            $touchedPhp[$final] = true;
        }
    }
    foreach ($plan['moves'] as $newRel) {
        if (str_ends_with($newRel, '.php')) {
            $touchedPhp[$newRel] = true;
        }
    }

    // 4. Regenerate both classmaps — the move changes every mapped path, and a
    //    stale map fails `composer check` (tests/Tooling/ClassmapTest.php).
    $generator = $root . '/tools/classmap-generate.php';
    if (is_file($generator)) {
        $cmd = 'php ' . escapeshellarg($generator) . ' --root=' . escapeshellarg($root) . ' 2>&1';
        exec($cmd, $genOut, $genStatus);
        if ($genStatus !== 0) {
            // The generator may not take --root; retry from the tree itself.
            $genOut = [];
            $cmd = 'cd ' . escapeshellarg($root) . ' && php tools/classmap-generate.php 2>&1';
            exec($cmd, $genOut, $genStatus);
        }
        $notes[] = 'classmap-generate: ' . ($genStatus === 0 ? 'ok' : 'FAILED') . ' — ' . trim(implode(' | ', $genOut));
        foreach (['agent/duo-classmap.php', 'cli/duo-classmap.php'] as $mapFile) {
            if (is_file($root . '/' . $mapFile)) {
                $touchedPhp[$mapFile] = true;
            }
        }
    }

    // 4a. Every name a templated require now resolves through the classmap
    //     must actually be IN the regenerated classmap, indexed the way the
    //     rewritten code indexes it — by the mapped path's basename. This is
    //     the check that would have caught agent/src/CommandRefusal.php, whose
    //     declared type is Duo\CommandRefusalException: a class-name lookup
    //     compiles fine and fatals at runtime instead.
    $unresolved = mm_unresolved_templated_names($root, $plan['templated_names'] ?? []);
    if ($unresolved !== []) {
        throw new RuntimeException(
            'move-modules: templated requires name source files the regenerated classmap does not carry: '
            . implode(', ', $unresolved)
            . ' — those requires would fatal at runtime; fix the map or the exclusion list before applying'
        );
    }

    // 4b. Golden-hash pins. sandbox/tests/regress_ecommerce_developer_static.sh
    //     hashes comment-stripped function blocks of
    //     sandbox/tests/grind_ecommerce_developer.sh; several of those blocks
    //     spell an agent/src path, so the move legitimately changes the text
    //     the pin covers. The new value is recomputed by the suite's OWN hash
    //     function (it prints `expected <a>, got <b>` on drift) rather than
    //     hand-typed, so the pin still means "this exact text", not "whatever
    //     is there now".
    foreach (mm_repin_golden_hashes($root) as $note) {
        $notes[] = $note;
    }

    // 5. tools/affected.php caches a path-keyed index; the move invalidates it.
    $cache = $root . '/sandbox/tmp/affected-index.json';
    if (is_file($cache)) {
        unlink($cache);
        $notes[] = 'deleted stale sandbox/tmp/affected-index.json';
    }

    // 6. Lint sweep. A move that leaves a file unparsable is the one failure
    //    mode that must never be reported as success.
    $lintFailures = [];
    foreach (array_keys($touchedPhp) as $relative) {
        $cmd = 'php -l ' . escapeshellarg($root . '/' . $relative) . ' 2>&1';
        exec($cmd, $lintOut, $lintStatus);
        if ($lintStatus !== 0) {
            $lintFailures[] = $relative . ': ' . trim(implode(' ', $lintOut));
        }
        $lintOut = [];
    }

    return [
        'moved' => $moved,
        'rewritten' => $rewritten,
        'lint_failures' => $lintFailures,
        'notes' => $notes,
        'linted' => count($touchedPhp),
    ];
}

/**
 * Re-pin the golden block hashes the move legitimately invalidated.
 *
 * Bounded and self-verifying: each pass replaces exactly the one hash the
 * suite named, and the loop ends when the suite stops reporting drift. A pin
 * that drifts for any other reason (a real edit to the grind script) is
 * outside this codemod's diff and would be re-pinned wrongly, so the loop
 * refuses to run when the working tree already carried a drift before the
 * move — which is why it is called only from --apply, after the rewrite.
 *
 * @return list<string> notes for the summary
 */
function mm_repin_golden_hashes(string $root): array
{
    $suite = 'sandbox/tests/regress_ecommerce_developer_static.sh';
    $path = $root . '/' . $suite;
    if (!is_file($path)) {
        return [];
    }
    $text = (string) file_get_contents($path);
    if (!str_contains($text, '_GOLDEN_HASH=')) {
        return [];
    }

    $notes = [];
    for ($pass = 0; $pass < 12; $pass++) {
        $output = [];
        exec('cd ' . escapeshellarg($root) . ' && bash ' . escapeshellarg($suite) . ' 2>&1', $output, $status);
        $joined = implode("\n", $output);
        $text = (string) file_get_contents($path);

        // Two message shapes, because the suite pins two kinds of block. The
        // first carries both values; the second carries only the new one, so
        // the constant is located structurally instead — from the `fail`
        // line's own text back to the comparison immediately above it.
        if (preg_match(
            '/comment-stripped executable block hash drifted: (\S+) \(expected ([0-9a-f]{64}), got ([0-9a-f]{64})\)/',
            $joined,
            $m
        ) === 1) {
            $label = $m[1];
            $old = $m[2];
            $new = $m[3];
        } elseif (preg_match(
            '/golden hash helper detected (.+?) drift \(got ([0-9a-f]{64})\)/',
            $joined,
            $m
        ) === 1) {
            $label = $m[1];
            $new = $m[2];
            $constant = mm_golden_constant_for($text, $label);
            if ($constant === null) {
                $notes[] = "GOLDEN HASH for '$label' drifted but its constant could not be located in $suite — re-pin by hand";
                break;
            }
            $old = $constant;
        } else {
            if ($pass > 0) {
                $notes[] = "re-pinned $pass golden block hash(es) in $suite";
            }
            break;
        }

        if ($old === $new || !str_contains($text, $old)) {
            $notes[] = "GOLDEN HASH for '$label' drifted but its recorded value is not in $suite — re-pin by hand";
            break;
        }
        file_put_contents($path, str_replace($old, $new, $text));
        $notes[] = "re-pinned $label golden block hash ($old -> $new)";
    }

    return $notes;
}

/**
 * Given the drift label a `golden hash helper detected <label> drift` message
 * carries, find the hash constant the failing comparison read. The `fail` line
 * quotes the label verbatim and the comparison sits on the line above it, so
 * the constant is recoverable without re-implementing the suite's hashing.
 */
function mm_golden_constant_for(string $text, string $label): ?string
{
    $lines = explode("\n", $text);
    foreach ($lines as $n => $line) {
        if (!str_contains($line, 'golden hash helper detected ' . $label . ' drift')) {
            continue;
        }
        for ($back = 0; $back <= 2 && $n - $back >= 0; $back++) {
            if (preg_match('/= "\$([A-Z0-9_]+_GOLDEN_HASH)"/', $lines[$n - $back], $m) === 1) {
                if (preg_match('/^' . preg_quote($m[1], '/') . '=([0-9a-f]{64})$/m', $text, $value) === 1) {
                    return $value[1];
                }
            }
        }
    }
    return null;
}

/**
 * @param list<string> $names file basenames a rewritten templated require will look up
 * @return list<string> the ones agent/duo-classmap.php cannot resolve
 */
function mm_unresolved_templated_names(string $root, array $names): array
{
    $mapFile = $root . '/agent/duo-classmap.php';
    if ($names === [] || !is_file($mapFile)) {
        return [];
    }
    /** @var mixed $map */
    $map = require $mapFile;
    if (!is_array($map)) {
        return $names;
    }
    $byBasename = [];
    foreach ($map as $path) {
        $byBasename[basename((string) $path, '.php')] = true;
    }
    $missing = [];
    foreach ($names as $name) {
        if (!isset($byBasename[$name])) {
            $missing[] = $name;
        }
    }
    sort($missing, SORT_STRING);
    return $missing;
}

// --------------------------------------------------------------------- main

/** @return array{mode:string, root:string, map:string, trees:list<string>} */
function mm_parse_args(array $argv): array
{
    $defaultRoot = dirname(__DIR__, 2);
    $options = ['mode' => '', 'root' => $defaultRoot, 'map' => '', 'trees' => ['all'], 'partial' => false];

    foreach (array_slice($argv, 1) as $arg) {
        if ($arg === '--plan' || $arg === '--apply') {
            if ($options['mode'] !== '') {
                throw new RuntimeException('move-modules: pass exactly one of --plan / --apply');
            }
            $options['mode'] = substr($arg, 2);
            continue;
        }
        if (str_starts_with($arg, '--root=')) {
            $options['root'] = substr($arg, 7);
            continue;
        }
        if (str_starts_with($arg, '--map=')) {
            $options['map'] = substr($arg, 6);
            continue;
        }
        if (str_starts_with($arg, '--tree=')) {
            $value = substr($arg, 7);
            if (!in_array($value, ['agent', 'cli', 'all'], true)) {
                throw new RuntimeException("move-modules: --tree must be agent, cli or all (got '$value')");
            }
            $options['trees'] = $value === 'all' ? ['all'] : [$value];
            continue;
        }
        if ($arg === '--allow-partial') {
            $options['partial'] = true;
            continue;
        }
        if ($arg === '--help' || $arg === '-h') {
            $options['mode'] = 'help';
            continue;
        }
        throw new RuntimeException("move-modules: unknown argument '$arg'");
    }

    if ($options['mode'] === '') {
        throw new RuntimeException('move-modules: pass --plan or --apply (see --help)');
    }
    $resolvedRoot = realpath($options['root']);
    if ($resolvedRoot === false) {
        throw new RuntimeException("move-modules: --root does not exist: {$options['root']}");
    }
    $options['root'] = $resolvedRoot;
    if ($options['map'] === '') {
        $options['map'] = $resolvedRoot . '/tools/modules.json';
    }
    return $options;
}

const MM_USAGE = <<<'TXT'
move-modules.php — move agent/src and cli/src into module directories,
keeping the flat `namespace Duo;` / `namespace Duo\Orchestrator;` declarations.

  --plan            print every move and every rewrite; change nothing
  --apply           perform them, regenerate both classmaps, lint the result
  --root=<dir>      repository root (default: this script's repo)
  --map=<file>      module map (default: <root>/tools/modules.json)
  --tree=agent|cli|all
                    restrict to one tree (default: all)
  --allow-partial   do not require the map to name every file in the tree.
                    For rehearsal and tests ONLY: the real train needs a total
                    map, and the totality guard is what proves it is one.

The module map is
  {"agent": {"root": "agent/src",
             "modules": {"Kernel": {"layer": "...", "files": ["Canon.php"]}},
             "keep": ["StaysPut.php"]},
   "cli":   {"root": "cli/src", "modules": {...}}}
A module named "." keeps its files where they are, as does anything in "keep".

TXT;

function mm_main(array $argv): int
{
    try {
        $options = mm_parse_args($argv);
    } catch (RuntimeException $e) {
        fwrite(STDERR, $e->getMessage() . "\n\n" . MM_USAGE);
        return 2;
    }

    if ($options['mode'] === 'help') {
        fwrite(STDOUT, MM_USAGE);
        return 0;
    }

    try {
        $map = mm_load_map($options['map'], $options['trees']);
        $plan = mm_compute($options['root'], $map, $options['partial']);
    } catch (RuntimeException $e) {
        fwrite(STDERR, $e->getMessage() . "\n");
        return 1;
    }

    if ($options['mode'] === 'plan') {
        mm_print_plan($plan, $map);
        return 0;
    }

    try {
        $result = mm_apply($options['root'], $plan);
    } catch (RuntimeException $e) {
        fwrite(STDERR, $e->getMessage() . "\n");
        return 1;
    }

    fwrite(STDOUT, "=== APPLIED ===\n");
    mm_print_summary(STDOUT, $plan, $map);
    fwrite(STDOUT, sprintf("  %d file(s) moved, %d rewritten, %d linted\n", $result['moved'], $result['rewritten'], $result['linted']));
    foreach ($result['notes'] as $note) {
        fwrite(STDOUT, "  note: $note\n");
    }
    foreach ($plan['dirname_sites'] as $site) {
        if ($site['kind'] !== 'dirname-base') {
            fwrite(STDOUT, sprintf("  REVIEW %s:%d %s -> %s (non-concat context)\n", $site['file'], $site['line'], $site['from'], $site['to']));
        }
    }
    foreach ($plan['review'] as $item) {
        fwrite(STDOUT, sprintf("  REVIEW %s:%d %s\n", $item['file'], $item['line'], $item['why']));
    }
    foreach ($plan['nearmiss'] as $item) {
        fwrite(STDOUT, sprintf("  REVIEW %s:%d non-canonical path spelling left untouched\n", $item['file'], $item['line']));
    }

    if ($result['lint_failures'] !== []) {
        fwrite(STDERR, "\n=== php -l FAILURES ===\n");
        foreach ($result['lint_failures'] as $failure) {
            fwrite(STDERR, "  $failure\n");
        }
        return 1;
    }
    fwrite(STDOUT, "  php -l: ok\n");
    return 0;
}

if (isset($_SERVER['SCRIPT_FILENAME']) && realpath((string) $_SERVER['SCRIPT_FILENAME']) === __FILE__) {
    // $_SERVER['argv'] rather than the bare $argv superglobal: PHPStan cannot
    // prove register_argc_argv is on (it always is under the CLI SAPI this
    // script runs on), so the bare form is a permanent false positive.
    /** @var list<string> $mmArgv */
    $mmArgv = $_SERVER['argv'] ?? [];
    exit(mm_main($mmArgv));
}
